  getRpsBetItems,
  updateRpsBetItems,
  qsbetitems,
  getQsBetItems,
  updateQsBetItems,
  predictedBetAmount,
  updateUserStrategy,
  betting,
  handleSwitchChange,
  handleDetachAttachChange,
  isDarkMode,
  solPrice,
  attached,
  qs_game_type,
  ai_mode,
